reference_solution:
def minimum_zeroing_operations(nums):
    stack=[];answer=0
    for value in nums:
        while stack and stack[-1]>value:stack.pop();answer+=1
        if value and (not stack or stack[-1]!=value):stack.append(value)
    return answer+len(stack)

